@php
    $latestConfiguration = $organization->effectiveConfigurations->first();
    $activeConfigurations = $organization->effectiveConfigurations;
    $syncStatus = !$latestConfiguration
        ? 'not_configured'
        : ($activeConfigurations->contains(fn ($configuration) => $configuration->synchronization_status === 'error')
            ? 'error'
            : ($activeConfigurations->contains(fn ($configuration) => $configuration->synchronization_status !== 'synced') ? 'pending' : 'synced'));
    $syncLabel = ['not_configured' => 'À configurer', 'pending' => 'À synchroniser', 'synced' => 'À jour', 'error' => 'Erreur de synchronisation'][$syncStatus];
    $syncVariant = ['not_configured' => 'neutral', 'pending' => 'warning', 'synced' => 'success', 'error' => 'danger'][$syncStatus];
    $configurableCount = collect($categories)->sum('field_count');
    $pendingCount = $activeConfigurations->where('synchronization_status', '!=', 'synced')->count();
@endphp
