            $formatValue = static function ($value): string {
                if (is_bool($value)) return $value ? 'Activé' : 'Désactivé';
                if ($value === null || $value === '') return 'Non défini';
                if (is_array($value)) return collect($value)->map(fn ($item, $key) => is_string($key) ? ucfirst(str_replace('_', ' ', $key)).' : '.$item : $item)->join(', ');
                return (string) $value;
            };
